// ============================================================================
// File: tb/v3/tb_ch01_fifo.v
// Module: tb_ch01_fifo
// Description:
//   Cycle-accurate testbench for rtl/v3/ch01_avalon_fifo.v:
//   - Reads cycle-by-cycle stimulus from tb_ch01_fifo_stim.txt.
//   - Reads expected trace from tb_ch01_fifo_expected.txt generated by Python twin.
//   - Compares bit-for-bit and cycle-for-cycle:
//     * mm_waitrequest
//     * st_valid
//     * st_data (when st_valid is asserted)
//     * dut.st_state (FSM state)
//     * dut.total_samples_used (CSR fill level)
//   - Covers >= 200 vectors including directed unpack/stall/back-to-back,
//     FIFO saturation, waitrequest assertion, overflow sticky flag,
//     and pseudo-random streaming with backpressure.
//   - Fully compatible with `iverilog -g2012 -Wall`.
// ============================================================================

`timescale 1ns/1ps

module tb_ch01_fifo;

    reg clk = 0;
    always #10 clk = ~clk; // 50 MHz clock (20 ns period)

    reg         rst_n;
    reg         mm_write;
    reg  [31:0] mm_writedata;
    wire        mm_waitrequest;

    reg         csr_read;
    reg  [2:0]  csr_address;
    wire [31:0] csr_readdata;

    wire [15:0] st_data;
    wire        st_valid;
    reg         st_ready;

    // Instantiate DUT
    ch01_avalon_fifo #(
        .ADDR_WIDTH(8) // 256 words = 512 samples
    ) dut (
        .clk(clk),
        .rst_n(rst_n),
        .mm_write(mm_write),
        .mm_writedata(mm_writedata),
        .mm_waitrequest(mm_waitrequest),
        .csr_read(csr_read),
        .csr_address(csr_address),
        .csr_readdata(csr_readdata),
        .st_data(st_data),
        .st_valid(st_valid),
        .st_ready(st_ready)
    );

    integer stim_fd;
    integer exp_fd;
    integer cycle_idx;
    integer errors;

    // Stimulus variables
    integer stim_w;
    reg [31:0] stim_wd;
    integer stim_rdy;

    // Expected variables
    integer exp_c;
    integer exp_w;
    reg [31:0] exp_wd;
    integer exp_wreq;
    integer exp_vld;
    integer exp_rdy;
    reg [15:0] exp_data;
    integer exp_state;
    integer exp_fill;

    initial begin
        rst_n = 0;
        mm_write = 0;
        mm_writedata = 32'd0;
        csr_read = 0;
        csr_address = 3'd0;
        st_ready = 0;
        cycle_idx = 0;
        errors = 0;

        // Open stimulus file
        stim_fd = $fopen("verify_v3/tb_ch01_fifo_stim.txt", "r");
        if (stim_fd == 0) stim_fd = $fopen("tb_ch01_fifo_stim.txt", "r");
        if (stim_fd == 0) begin
            $display("ERROR: Cannot open tb_ch01_fifo_stim.txt");
            $finish;
        end

        // Open expected trace file
        exp_fd = $fopen("verify_v3/tb_ch01_fifo_expected.txt", "r");
        if (exp_fd == 0) exp_fd = $fopen("tb_ch01_fifo_expected.txt", "r");
        if (exp_fd == 0) begin
            $display("ERROR: Cannot open tb_ch01_fifo_expected.txt");
            $finish;
        end

        // Reset pulse
        repeat (3) @(negedge clk);
        rst_n = 1;
        @(negedge clk);

        $display("=== STARTING CH01 AVALON FIFO CYCLE-BY-CYCLE VERIFICATION ===");

        // Run cycle-by-cycle
        while ($fscanf(stim_fd, "%d %h %d\n", stim_w, stim_wd, stim_rdy) == 3 &&
               $fscanf(exp_fd, "%d %d %h %d %d %d %h %d %d\n",
                       exp_c, exp_w, exp_wd, exp_wreq, exp_vld, exp_rdy, exp_data, exp_state, exp_fill) == 9) begin

            // Drive inputs before posedge clk
            mm_write     <= (stim_w != 0) ? 1'b1 : 1'b0;
            mm_writedata <= stim_wd;
            st_ready     <= (stim_rdy != 0) ? 1'b1 : 1'b0;

            // Wait for posedge clk (RTL updates) and then check at negedge clk (stable)
            @(posedge clk);
            #1; // Short delta after posedge

            // Check outputs against expected
            if (mm_waitrequest !== ((exp_wreq != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: waitrequest mismatch (got %b, exp %0d)",
                         cycle_idx, mm_waitrequest, exp_wreq);
                errors = errors + 1;
            end

            if (st_valid !== ((exp_vld != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: st_valid mismatch (got %b, exp %0d)",
                         cycle_idx, st_valid, exp_vld);
                errors = errors + 1;
            end

            if (st_valid && (st_data !== exp_data)) begin
                $display("[FAIL] Cycle %0d: st_data mismatch (got 0x%04x, exp 0x%04x)",
                         cycle_idx, st_data, exp_data);
                errors = errors + 1;
            end

            if (dut.st_state !== exp_state[1:0]) begin
                $display("[FAIL] Cycle %0d: FSM state mismatch (got %0d, exp %0d)",
                         cycle_idx, dut.st_state, exp_state);
                errors = errors + 1;
            end

            if (dut.total_samples_used !== exp_fill[9:0]) begin
                $display("[FAIL] Cycle %0d: fill level mismatch (got %0d, exp %0d)",
                         cycle_idx, dut.total_samples_used, exp_fill);
                errors = errors + 1;
            end

            if (errors >= 20) begin
                $display("Too many errors. Aborting simulation.");
                $finish;
            end

            cycle_idx = cycle_idx + 1;
        end

        $fclose(stim_fd);
        $fclose(exp_fd);

        $display("Simulation completed %0d cycles.", cycle_idx);
        $display("Total comparison errors: %0d", errors);

        if (errors == 0 && cycle_idx >= 200) begin
            $display("=== [PASS] CH01 AVALON FIFO MATCHED PYTHON TWIN BIT-FOR-BIT AND CYCLE-FOR-CYCLE ON %0d CYCLES ===", cycle_idx);
        end else begin
            $display("=== [FAIL] CH01 AVALON FIFO FAILED WITH %0d ERRORS ===", errors);
        end

        $finish;
    end

endmodule
